/// <summary>
/// CB395_CSDFulfilementInterBranchTransfer.
/// Class responsible for creating CSD transfer orders involving bulk transfer for transfer order.
/// </summary>
class METCreateCSDTransferOrder_BulkTransferToSupplyWarehouse extends METCreateCSDTransferOrder
{
    InventLocationId reqMainWarehouse;
    Map              groupingMap;
    boolean          skipTransferLine;

}

Method.Source:
/// <summary>
/// Gets grouping key.
/// </summary>
/// <returns>Grouping key.</returns>
private container getGroupingKey()
{
    return [salesLine.ItemId,
            salesLine.SalesUnit,
            reqMainWarehouse,
            salestable.InventLocationId];
}

/// <summary>
/// Gets grouping map value. It also restors table variables used.
/// </summary>
/// <returns>Grouping map value.</returns>
private container getGroupingValue()
{
    return [transferTable,
           transferLine,
           salesLine,
           salesTable];
}

/// <summary>
/// Sets table variables from container provided.
/// </summary>
/// <param name = "_value">Value.</param>
private void setFromGroupingValue(container _value)
{
    [transferTable,
     transferLine,
     salesLine,
     salesTable] = _value;

    metTransferTable = transferTable.metInventTransferTableExt();
    metTransferLine  = transferLine.metInventTransferLine();
}

/// <summary>
/// Initializes variables.
/// </summary>
protected void init()
{
    super();

    groupingMap = new Map(Types::Container, Types::Container);
}

/// <summary>
/// Initializes transfer order records.
/// </summary>
protected void initTransferOrder()
{
    reqMainWarehouse = salesLine.metReqMainWarehouse();

    if (!reqMainWarehouse)
    {
        return;
    }

    if (groupingMap.exists(this.getGroupingKey()))
    {
        container value;
        SalesQty  qty;

        qty = salesLine.SalesQty;
        value = groupingMap.lookup(this.getGroupingKey());
        this.setFromGroupingValue(value);

        transferLine.QtyTransfer += qty;
    }
    else
    {
        super();
    }

    groupingMap.insert(this.getGroupingKey(), this.getGroupingValue());
}

/// <summary>
/// Initializes transfer table record.
/// </summary>
protected void initTransferTable()
{
    super();

    transferTable.InventLocationIdFrom = reqMainWarehouse;
}

/// <summary>
/// Initializes records for creation.
/// </summary>
protected void initRecords()
{
    super();

    this.addGroupedRecords();
}

/// <summary>
/// Adds group record into
/// </summary>
private void addGroupedRecords()
{
    MapEnumerator mapEnum;
    container     value;

    mapEnum = groupingMap.getEnumerator() as MapEnumerator;

    while (mapEnum && mapEnum.moveNext())
    {
        value = mapEnum.currentValue();
        skipTransferLine = false;

        this.setFromGroupingValue(value);
        this.applyRules();

        if (!skipTransferLine)
        {
            this.addToTransferOrderMap();
        }
    }
}

protected void applyUOMConversionRule(METFulfilmentRuleApply _apply)
{
    super(_apply);

    if (salesLine.SalesUnit == METConstants::unitEach)
    {
        if (_apply == METFulfilmentRuleApply::RemainderToEA)
        {
            Qty qtyCalculated = unitConvStoredQty - unitConvConvertedQty;

            if (qtyCalculated > 0)
            {
                transferLine.QtyTransfer = qtyCalculated;
            }
            else
            {
                skipTransferLine = true;
            }
        }
        else if (_apply == METFulfilmentRuleApply::RemainderToEAResidualInv)
        {
            Qty qtyCalculated = unitConvStoredQty - unitConvConvertedQty;
            Qty qtyOnHand = transferLine.metOnHandInventory();
            Qty qtyResidual = qtyOnHand - qtyCalculated;

            if (qtyResidual > 0)
            {
                skipTransferLine = true;
            }
            else
            {
                transferLine.QtyTransfer = unitConvFactor;
            }

        }
    }
}
